SELECT e.event_id, e.category_id, e.title, e.start_dt AS startDt, e.end_dt AS endDt, e.views, e.like_count, f.file_url AS imgUrl FROM event e LEFT JOIN files f ON f.entity_type = 'EVENT' AND f.entity_id = e.event_id AND f.file_role = 'THUMB' WHERE e.event_se = 'EVT'
AND e.category_id = #{searchType}
AND e.category_id = #{categoryId}
AND e.title LIKE CONCAT('%', #{searchValue}, '%')
ORDER BY e.like_count DESC, e.event_id DESC
ORDER BY e.views DESC, e.event_id DESC
ORDER BY e.event_id DESC
LIMIT #{size} OFFSET #{offset}

